// Stored normalized drawing operations survive DPR, layout and viewport changes.
export class WritingBoard{
 constructor(canvas,{color='#315e91',width=5,lines=true,canDraw=()=>true,onChange=()=>{}}={}){Object.assign(this,{canvas,color,width,lines,canDraw,onChange});this.tool='pen';this.operations=[];this.active=new Map();this.redraw=this.redraw.bind(this);this.observer=new ResizeObserver(this.redraw);this.observer.observe(canvas);canvas.style.touchAction='none';canvas.onpointerdown=e=>this.down(e);canvas.onpointermove=e=>this.move(e);canvas.onpointerup=e=>this.up(e);canvas.onpointercancel=e=>this.up(e);canvas.onlostpointercapture=e=>this.up(e);this.redraw();}
 point(e){const r=this.canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/Math.max(1,r.width))),y:Math.max(0,Math.min(1,(e.clientY-r.top)/Math.max(1,r.height))),p:e.pressure||.5};}
 down(e){if(!this.canDraw())return;if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();e.stopPropagation();this.canvas.setPointerCapture(e.pointerId);const op={tool:this.tool,color:this.color,width:this.width,points:[this.point(e)]};this.operations.push(op);this.active.set(e.pointerId,op);this.redraw();}
 move(e){if(!this.canDraw()){this.cancel();return;}const op=this.active.get(e.pointerId);if(!op)return;e.preventDefault();e.stopPropagation();const samples=e.getCoalescedEvents?.();for(const v of samples?.length?samples:[e]){const p=this.point(v),old=op.points.at(-1);if(Math.hypot(p.x-old.x,p.y-old.y)>.0004)op.points.push(p);}this.redraw();}
 up(e){if(!this.active.has(e.pointerId))return;e.preventDefault?.();e.stopPropagation?.();this.active.delete(e.pointerId);if(this.canvas.hasPointerCapture?.(e.pointerId))this.canvas.releasePointerCapture(e.pointerId);this.onChange(this.operations);}
 cancel(){for(const id of this.active.keys())if(this.canvas.hasPointerCapture?.(id))this.canvas.releasePointerCapture(id);this.active.clear();}
 undo(){this.cancel();this.operations.pop();this.redraw();this.onChange(this.operations);}
 clear(){this.cancel();this.operations=[];this.redraw();this.onChange(this.operations);}
 redraw(){const r=this.canvas.getBoundingClientRect(),dpr=Math.min(globalThis.devicePixelRatio||1,2),w=Math.max(1,Math.round(r.width*dpr)),h=Math.max(1,Math.round(r.height*dpr));if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;}const c=this.canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);for(const op of this.operations){const p=op.points;c.globalCompositeOperation=op.tool==='eraser'?'destination-out':'source-over';c.strokeStyle=op.color;c.fillStyle=op.color;c.lineWidth=op.width*(op.tool==='eraser'?4:1);c.lineCap='round';c.lineJoin='round';if(p.length===1){c.beginPath();c.arc(p[0].x*r.width,p[0].y*r.height,c.lineWidth/2,0,Math.PI*2);c.fill();}else{c.beginPath();c.moveTo(p[0].x*r.width,p[0].y*r.height);for(let i=1;i<p.length-1;i++){const mid={x:(p[i].x+p[i+1].x)/2,y:(p[i].y+p[i+1].y)/2};c.quadraticCurveTo(p[i].x*r.width,p[i].y*r.height,mid.x*r.width,mid.y*r.height);}c.lineTo(p.at(-1).x*r.width,p.at(-1).y*r.height);c.stroke();}}c.globalCompositeOperation='source-over';}
 dispose(){this.cancel();this.observer.disconnect();const c=this.canvas;c.onpointerdown=c.onpointermove=c.onpointerup=c.onpointercancel=c.onlostpointercapture=null;}
}
